/*
 * prog50_binary_heap – a tiny command‑line min‑heap.
 *
 * Behaviour (matches the original binary):
 *
 *   * If no arguments are given, prints "NOOP".
 *
 *   * Arguments are processed left‑to‑right.
 *
 *   *  I<number>   – insert the signed decimal integer <number>.
 *                    * If the argument after the leading ‘I’ is not a
 *                      valid integer → prints "ERR".
 *                    * If the heap already contains 10 elements → prints "FULL".
 *                    * Otherwise the value is inserted and the program prints
 *                      "INS %ld\n" with the inserted value.
 *
 *   *  X          – extract the minimum element from the heap.
 *                    * If the heap is empty → prints "EMPTY".
 *                    * Otherwise the minimum is removed.
 *                      After removal, if the heap becomes empty it prints
 *                      "EMPTY", otherwise it prints the new minimum as
 *                      "MIN %ld\n".
 *
 *   *  any other argument → prints "ERR".
 *
 * The heap is a classic binary min‑heap stored in a static array of capacity 10.
 * All output is performed with `puts` (adds a trailing newline) or `printf`
 * exactly as the original binary does.
 */

#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

#define CAPACITY 10

static long heap[CAPACITY];
static int  size = 0;

/* Helper: swap two elements in the heap array. */
static void swap(int i, int j)
{
    long tmp = heap[i];
    heap[i]   = heap[j];
    heap[j]   = tmp;
}

/* Insert a value into the min‑heap (assumes there is space). */
static void heap_insert(long value)
{
    int i = size;               /* index where we place the new value */
    heap[i] = value;
    ++size;

    /* bubble‑up */
    while (i > 0) {
        int parent = (i - 1) / 2;
        if (heap[parent] <= heap[i])
            break;
        swap(parent, i);
        i = parent;
    }
}

/* Remove the minimum element (root) and re‑heapify. */
static void heap_extract_min(void)
{
    if (size == 0)
        return;                 /* should never be called in this case */

    heap[0] = heap[size - 1];
    --size;

    /* heapify‑down */
    int i = 0;
    while (1) {
        int left  = 2 * i + 1;
        int right = left + 1;
        int smallest = i;

        if (left < size && heap[left] < heap[smallest])
            smallest = left;
        if (right < size && heap[right] < heap[smallest])
            smallest = right;

        if (smallest == i)
            break;

        swap(i, smallest);
        i = smallest;
    }
}

int main(int argc, char **argv)
{
    if (argc < 2) {
        puts("NOOP");
        return 0;
    }

    for (int idx = 1; idx < argc; ++idx) {
        const char *arg = argv[idx];

        /* INSERT command – starts with 'I' */
        if (arg[0] == 'I') {
            char *endptr;
            errno = 0;
            long val = strtol(arg + 1, &endptr, 10);

            if (*endptr != '\0' || errno != 0) {
                puts("ERR");
                continue;
            }

            if (size >= CAPACITY) {
                puts("FULL");
                continue;
            }

            heap_insert(val);
            printf("INS %ld\n", val);
            continue;
        }

        /* EXTRACT command – exactly "X" */
        if (strcmp(arg, "X") == 0) {
            if (size == 0) {
                puts("EMPTY");
                continue;
            }

            heap_extract_min();

            if (size == 0) {
                puts("EMPTY");
            } else {
                printf("MIN %ld\n", heap[0]);
            }
            continue;
        }

        /* Anything else is an error */
        puts("ERR");
    }

    return 0;
}
